        "certification": "PENDING_AUDIT_EVIDENCE",
        "work_completion": "PENDING_CERTIFICATION",
        "percent_complete": 95,
    }

    if result.get("status") == "READ_ONLY_COMPLETE":
        readonly_evidence = sanitize_readonly_evidence(result)
